from concurrent.futures import ThreadPoolExecutor
import pytest


def parity(x: int) -> int:
    """Return the parity of x (0 for even, 1 for odd)."""
    return x % 2


def parities(xs: list[int], max_workers: int | None = None) -> list[int]:
    """Return the parity of each element in xs, computed in parallel, in input order."""
    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        return list(executor.map(parity, xs))


def test_parities_empty() -> None:
    assert parities([]) == []


def test_parities_single() -> None:
    assert parities([0]) == [0]
    assert parities([1]) == [1]
    assert parities([2]) == [0]


def test_parities_negative_numbers() -> None:
    assert parities([-3, -2, -1, 0]) == [1, 0, 1, 0]


def test_parities_preserves_order() -> None:
    xs = [1, 2, 4, 7, 10, 13, 16, 17]
    expected = [1, 0, 0, 1, 0, 1, 0, 1]
    assert parities(xs) == expected


@pytest.mark.parametrize("workers", [1, 2, 4, 16])
def test_parities_worker_counts(workers: int) -> None:
    xs = list(range(100))
    expected = [x % 2 for x in xs]
    assert parities(xs, max_workers=workers) == expected

